{small eigenvalues} 
With the above notation, for Riemannian foliations on closed Riemannian manifolds we have
\begin{align}
\dim{\widehat E}_1^r&=
\sharp\,\left\{i\ \left|\ \lambda_i^r(h)\in O\left(h^2\right)
\quad\text{as}\quad h\downarrow 0\right.\right\}\;,\label{e:small eigenvalues 1}\\
\dim E_k^r&=
\sharp\,\left\{i\ \left|\ \lambda_i^r(h)\in O\left(h^{2k}\right)
\quad\text{as}\quad h\downarrow 0\right.\right\}\;,\quad k\geq2\;.
\label{e:small eigenvalues k}
\end{align}

{asymptotics of eigenforms}
For any Riemannian foliation on a closed manifold with a bundle-like metric, let $\omega_i$ be a sequence in
$\Omega^r$ such that $\|\omega_i\|=1$ and 
\begin{equation}\label{e:asymptotics of eigenforms}
\left\langle\text{$\Delta$}_{h_i}\omega_i,\omega_i\right\rangle\in o\left(h_i^{2(k-1)}\right)
\end{equation}
for some $k=1,2,3,\dots$ and some sequence $h_i\downarrow0$. Then some subsequence
of the $\omega_i$ is strongly convergent, and its limit is in 
$L^2\text{$\mathcal{H}$}_1^r$ for $k=1$, and in
$\text{$\mathcal{H}$}_k^r$ for $k\geq2$.

{frakHk0,p} 
Let \text{$\mathcal{F}$}\ be a Riemannian foliation of dimension $p$ on a closed manifold $M$. We have:
\begin{itemize}

\item[$($i$)$] There is a bundle-like metric $g$ on $M$ such that
${\mathfrak H}_2^{0,p}(g)=\text{$\mathcal{H}$}_2^{0,p}(g)$. 

\item[$($ii$)$] If $\bar0_1^{0,p}\neq0$, then
there is a bundle-like metric $g'$ on $M$ such that ${\mathfrak H}_2^{0,p}(g')=0$. 

\end{itemize}

{frakHk} 
Let \text{$\mathcal{F}$}\ be a Riemannian foliation on a closed manifold $M$. If $\bar0_1=0$, then 
${\mathfrak H}_k(g)=\text{$\mathcal{H}$}_k(g)$ for every $k\ge1$ and any bundle-like metric $g$ on $M$.

{barbfo1,hatbfe1}
We have
\begin{gather*}
\bar{\mathbf o}_1^{u,v}=\frac{D^{u,v}\cap\operatorname{cl}_0\left({\mathbf d}_{0,1}D^{u,v-1}\right)}
{{\mathbf d}_{0,1}D^{u,v-1}}
=\frac{D^{u,v}\cap\operatorname{cl}_0\left(d_{0,1}\Omega^{u,v-1}\right)}
{{\mathbf d}_{0,1}D^{u,v-1}}\;,\\
\hat{\mathbf e}_1^{u,v}=\frac{D^{u,v}\cap\ker{\mathbf d}_{0,1}}
{D^{u,v}\cap\operatorname{cl}_0\left({\mathbf d}_{0,1}D^{u,v-1}\right)}
=\frac{D^{u,v}\cap\ker{\mathbf d}_{0,1}}{D^{u,v}
\cap\operatorname{cl}_0\left(d_{0,1}\Omega^{u,v-1}\right)}\;.
\end{gather*}

{tildebfe1}
For $r=u+v$, we have
\begin{gather*}
\tilde\pi_{u,v}\left(\operatorname{cl}_0(\text{$\mathcal{B}$}_v)\right)=\widetilde{D}^{u,v}\cap\operatorname{cl}_0({\text{$\mathcal{B}$}}_v)\;,\\
\tilde\pi_{u,v}\left(\text{$\mathcal{Z}$}_{v-1}\right)=D^{u+1,v-1}\cap{\text{$\mathcal{Z}$}}_{v-1}
=D^{u+1,v-1}\cap\ker{\mathbf d}_{0,1}\;,
\end{gather*}
and thus
$$
\tilde{{\mathbf e}}_1^{u,v}
=\frac{\widetilde{D}^{u,v}\cap\operatorname{cl}_0({\text{$\mathcal{B}$}}_v)}{D^{u+1,v-1}\cap\ker{\mathbf d}_{0,1}}\;.
$$

By the commutativity of the diagram
$$
\begin{CD}
H(e_1) & @>>> &H({\mathbf e}_1)\\
@VVV & & @VVV\\
H(\hat e_1) &@>>> &H(\hat{\mathbf e}_1)\;,
\end{CD}
$$
where all maps are canonical, the result follows directly from Theorem~\ref{t:H1}-(vii),
Corollaries~\ref{c:H(hate1)=H(hatbfe1)} and~\ref{c:H(bfe_1)=H(hatbfe_1)}.

{leq}
Observe that, by Theorem~\ref{t:Ek=bfEk}, Corollary~\ref{c:bfEkr Hausdorff of finite dim} holds for Riemannian foliations and
$k=2$, and inequality ``$\leq$'' of \eqref{e:small eigenvalues k} in Theorem~\ref{mt:small eigenvalues} follows.

{decomposition of calAr}
The following properties are satisfied:
\begin{itemize}

\item[$($i$)$] There is a $($non-canonical$)$ isomorphism
\begin{align*}
\text{$\mathcal{A}$}^r&\cong E_\infty^r\oplus\bigoplus_\ell\left(\left(E_\ell^r\cap\operatorname{im} d_\ell\right)
\oplus\frac{E_\ell^r}{E_\ell^r\cap\ker d_\ell}\right)\\
&=\bigoplus_{u+v=r}\left(E_\infty^{u,v}\oplus\bigoplus_\ell\left(\left(E_\ell^{u,v}\cap\operatorname{im}
d_\ell\right)\oplus\frac{E_\ell^{u,v}}{E_\ell^{u,v}\cap\ker d_\ell}\right)\right)\;.
\end{align*}

\item[$($ii$)$] The isomorphism in $($i$)$ can be chosen so that $\text{$\mathcal{A}$}_k^r$ corresponds to
$$
\bigoplus_{u\geq k,\ u+v=r}
\left(E_\infty^{u,v}\oplus\bigoplus_\ell\left(\left(E_\ell^{u,v}\cap\operatorname{im}
d_\ell\right)\oplus\frac{E_\ell^{u,v}}{E_\ell^{u,v}\cap\ker d_\ell}\right)\right)\;.
$$

\item[$($iii$)$] The isomorphism in $($i$)$ can be
chosen so that the only possibly non-trivial components of the operator corresponding to $d$ by
$($i$)$ are the isomorphisms
$$\bar d_\ell:\frac{E_\ell^{u,v}}{E_\ell^{u,v}\cap\ker d_\ell}\text{$\longrightarrow$}
E_\ell^{u+\ell,v-\ell+1}\cap\operatorname{im} d_\ell$$
canonically defined by $d_\ell$.

\end{itemize}

{m}
We have 
$$\dim E_k^r=m_k^{r-1}+H^r(\text{$\mathcal{A}$},d)+m_k^r\;.$$

{L}
For $r=u+v$, there is a subspace $L_k^{u,v}\subset\text{$\mathcal{A}$}^r/(\text{$\mathcal{A}$}^r\cap\ker d)$ such that:
\begin{itemize}

\item[$($i$)$] We have
$$
\frac{Z_k^{u,v}+(\text{$\mathcal{A}$}^r\cap\ker d)}{\text{$\mathcal{A}$}^r\cap\ker d}
=L_k^{u,v}\oplus\frac{Z_{k-1}^{u+1,v-1}+(\text{$\mathcal{A}$}^r\cap\ker d)}{\text{$\mathcal{A}$}^r\cap\ker d}
$$
as vector spaces. In particular $\bar d\left(L_k^{u,v}\right)\subset
\text{$\mathcal{A}$}_{u+k}^{r+1}$.

\item[$($ii$)$] The direct sum $L_k^r=\bigoplus_{u+v=r}L_k^{u,v}$ makes sense in
$\text{$\mathcal{A}$}^r/(\text{$\mathcal{A}$}^r\cap\ker d)$, and we have $\dim L_k^r=m_k^r$.

\end{itemize}

>From Lemma~\ref{l:decomposition of calAr} we get a (non-canonical) isomorphism
\begin{equation}\label{e:A/ker d}
\frac{\text{$\mathcal{A}$}^r}{\text{$\mathcal{A}$}^r\cap\ker d}
\cong\bigoplus_\ell\frac{E_\ell^r}{E_\ell^r\cap\ker d_\ell}\;,
\end{equation}
Then let $L_k^{u,v}$ be the subspace of $\text{$\mathcal{A}$}^r/(\text{$\mathcal{A}$}^r\cap\ker d)$ that corresponds to
$$
\bigoplus_{l\geq k}\frac{E_\ell^{u,v}}{E_\ell^{u,v}\cap\ker d_\ell}
$$
by \eqref{e:A/ker d}. Then property~(i) easily follows from Lemma~\ref{l:decomposition of calAr}, and
property~(ii) is obvious; in fact, $L_k^r$ corresponds to
$$
\bigoplus_{l\geq k}\frac{E_\ell^r}{E_\ell^r\cap\ker d_\ell}
$$
by \eqref{e:A/ker d}.

{L}
By Corollary~\ref{c:L}-(i), the canonical isomorphism
\begin{equation}\label{e:Z/Z=Z/ker d}
\frac{Z_k^{u,v}}{Z_{k-1}^{u+1,v-1}+Z_\infty^{u,v}}\stackrel{\cong}{\text{$\longrightarrow$}}
\frac{Z_k^{u,v}+(\text{$\mathcal{A}$}^r\cap\ker d)}
{Z_{k-1}^{u+1,v-1}+(\text{$\mathcal{A}$}^r\cap\ker d)}
\end{equation}
yields
$$
\frac{Z_k^{u,v}}{Z_{k-1}^{u+1,v-1}+Z_\infty^{u,v}}\cong L_k^{u,v}\;.
$$

{hat e1k}
For $k\ge1$, we have a canonical isomorphism
\begin{equation}\label{e:hate1,ku,v=...}
\hat e_{1,k}^{u,v}\cong
\frac{z_k^{u,v}+\overline{b_0^{u,v}}}{b_{k-1}^{u,v}+\overline{b_0^{u,v}}}
\end{equation}
of topological vector spaces. Moreover, for $k\ge2$, the above isomorphism $e_k^{u,v}\cong\hat
e_{1,k}^{u,v}$ corresponds to the canonical map
\begin{equation}\label{e:zku,v/bk-1u,v to ...}
\frac{z_k^{u,v}}{b_{k-1}^{u,v}}
\text{$\longrightarrow$}\frac{z_k^{u,v}+\overline{b_0^{u,v}}}{b_{k-1}^{u,v}+\overline{b_0^{u,v}}}
\end{equation}
when applying \eqref{e:hate1,ku,v=...}.

{summarize} 
The inverse of the isomorphism
$\hat e_{1,k}^{u,v}\stackrel{\cong}{\to}\text{$\mathcal{H}$}_k^{u,v}$ in Lemma~\ref{l:calHk} is obviously induced by the
inclusion $\text{$\mathcal{H}$}_k^{u,v}\hookrightarrow z_k^{u,v}+\overline{b_0^{u,v}}$. So we can summarize
Lemmas~\ref{l:hat e1k} and~\ref{l:calHk} by saying that, for $k\ge2$, the isomorphism
$e_k^{u,v}\cong\text{$\mathcal{H}$}_k^{u,v}$ is given by the diagram
\begin{equation}\label{e:summarize}
e_k^{u,v}=\frac{z_k^{u,v}}{b_{k-1}^{u,v}}\stackrel{\cong}{\text{$\longrightarrow$}}
\hat e_{1,k}^{u,v}=\frac{z_k^{u,v}+\overline{b_0^{u,v}}}{b_{k-1}^{u,v}+\overline{b_0^{u,v}}}
\stackrel{\cong}{\longleftarrow}\text{$\mathcal{H}$}_k^{u,v}\;,
\end{equation}
where both isomorphisms are canonically induced by inclusions.

{dk in calHk}
Let $\omega\in\text{$\mathcal{H}$}_k^{u,v}$ and $\gamma\in\text{$\mathcal{H}$}_k^{u+k,v-k+1}$ for $k\geq2$. If there is a
sequence $\alpha_i\in\Omega_{u+1}^{u+v}$ such that
\begin{gather*}
\pi_{u+a,v-a+1}d(\omega+\alpha_i)\text{$\longrightarrow$}0\;,\quad 0<a<k\;,\\
\bar Q_{k-2}\pi_{u+k,v-k+1}d(\omega+\alpha_i)\text{$\longrightarrow$}0\;,\quad
\Pi_k\pi_{u+k,v-k+1}d(\omega+\alpha_i)\text{$\longrightarrow$}\gamma
\end{gather*}
strongly in $\boldsymbol{\Omega}$, then $d_k\omega=\gamma$. Moreover, in this case the
sequence $\alpha_i$ can be chosen so that 
\begin{gather*}
\pi_{u+a,v-a+1}d(\omega+\alpha_i)\text{$\longrightarrow$}0\;,\quad 0<a<k\;,\\
\pi_{u+k,v-k+1}d(\omega+\alpha_i)\to\gamma
\end{gather*} 
with respect to the \text{$C^\infty$}~topology in $\Omega$.

{dk=0 in calHk}
Let $\gamma\in\text{$\mathcal{H}$}_k^{u+k,v-k+1}$ for $k\geq2$. If there is some sequence
$\alpha_i\in\Omega_{u+1}^{u+v}$, such that
\begin{gather*}
\pi_{u+a,v-a+1}d\alpha_i\text{$\longrightarrow$}0\;,\quad 0<a<k\;,\\
\bar Q_{k-2}\pi_{u+k,v-k+1}d\alpha_i\text{$\longrightarrow$}0\;,\quad
\Pi_k\pi_{u+k,v-k+1}d\alpha_i\text{$\longrightarrow$}\gamma
\end{gather*}
strongly in $\boldsymbol{\Omega}$, then $\gamma=0$.

{Pil+1 piu+l,v-l d alpha}
For $\alpha\in\widetilde\text{$\mathcal{H}$}_\ell^{u,v}$, if $\tilde d_\ell\alpha=0$, then
$\Pi_{\ell+1}\pi_{u+\ell+1,v-\ell}d\alpha=0$.

{tildeDl is self-adjoint}
The operator $\widetilde D_\ell$ is essentially self-adjoint in
$L^2\widetilde\text{$\mathcal{H}$}_\ell^{\cdot,v}$.

{WrtildecalHl}
$D\widetilde\Pi_{\ell;\cdot,v}-\widetilde\Pi_{\ell;\cdot,v}D\widetilde\Pi_{\ell;\cdot,v}$ defines
a bounded operator on $\boldsymbol{\Omega}$.

{deltak in calHk}
Let $\omega\in\text{$\mathcal{H}$}_k^{u,v}$ and $\gamma\in\text{$\mathcal{H}$}_k^{u-k,v+k-1}$ for $k\geq2$. If there is a
sequence $\beta_i\in\bigoplus_{a>0}\Omega^{u-a,v+a}$ such that
\begin{gather*}
\pi_{u-a,v+a-1}\delta(\omega+\beta_i)\text{$\longrightarrow$}0\;,\quad 0<a<k\;,\\
\bar P_{k-2}\pi_{u-k,v+k-1}\delta(\omega+\beta_i)\text{$\longrightarrow$}0\;,\quad
\Pi_k\pi_{u-k,v+k-1}\delta(\omega+\beta_i)\text{$\longrightarrow$}\gamma
\end{gather*}
strongly in $\boldsymbol{\Omega}$, then $\delta_k\omega=\gamma$. Moreover, in this case the
sequence $\beta_i$ can be chosen so that 
\begin{gather*}
\pi_{u-a,v+a-1}\delta(\omega+\beta_i)\text{$\longrightarrow$}0\;,\quad 0<a<k\;,\\
\pi_{u-k,v+k-1}\delta(\omega+\beta_i)\text{$\longrightarrow$}\gamma
\end{gather*} 
with respect to the \text{$C^\infty$}~topology in $\Omega$.

\label{claim:frakH2} 
A differential form $\omega\in\Omega$ is in ${\mathfrak H}_2$ if and only if it has extensions
$\tilde\omega_1(h),\tilde\omega_2(h)\in\Omega[h]$ satisfying
\begin{equation}\label{e:frakH2}
d_h\tilde\omega_1(h)\in h^2\Omega[h]\;,\quad\delta_h\tilde\omega_2(h)\in h^2\Omega[h]\;.
\end{equation}

\label{asymptotics of eigenforms}
For any Riemannian foliation on a closed manifold with a bundle-like metric, let $\omega_i$ be a sequence in
$\Omega^r$ such that $\|\omega_i\|=1$ and
\begin{equation}\label{e:asymptotics of eigenforms}
\left\langle\Delta_{h_i}\omega_i,\omega_i\right\rangle\in o\big(h_i^{2(k-1)}\big)
\end{equation}
for some fixed integer $k\ge1$ and some sequence $h_i\downarrow0$. Then,  if $k\geq2$ {\rm(}resp. $k=1${\rm)}, some subsequence of $\omega_i$ is strongly {\rm(}resp., weakly {\rm)} convergent in $\boldsymbol{\Omega}$, and its limit is in $\mathcal{H}_k^r$ {\rm(}resp., $L^2\mathcal{H}_1^r${\rm)}.
